package com.example.domain.model.i18n

internal object DuaTl1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Pagkagising", "Papuri sa Allah na muling nagbigay-buhay sa amin matapos kaming patayin (paidlipin), at sa Kanya ang pagbabalik.", "Binibigkas kaagad pagkagising bilang pasasalamat sa Allah.", "Binibigkas ito ng Propeta ﷺ tuwing gigising — pagsisimula ng araw na may pasasalamat at pag-alala sa kabilang buhay."),
        "dua_leaving_home" to DuaText("Paglabas ng bahay", "Sa ngalan ng Allah, nagtitiwala ako sa Allah, walang lakas o kapangyarihan maliban sa Allah.", "Binibigkas paglabas ng bahay para sa proteksyon.", "Sasabihin sa kanya: ginabayan ka, natugunan ang iyong pangangailangan, at ikaw ay pinrotektahan — at lalayo sa kanya ang satanas."),
        "dua_anxiety_distress" to DuaText("Panalangin laban sa pag-aalala at kalungkutan", "O Allah, nagpapakupkop ako sa Iyo laban sa pag-aalala at kalungkutan, sa kahinaan at katamaran, sa kuripot at kaduwagan, sa bigat ng utang at pang-aapi ng tao.", "Sa oras ng pag-aalala, kalungkutan, utang, at kirot ng damdamin.", "Madalas bigkasin ito ng Propeta ﷺ upang magpakupkop laban sa lungkot, katamaran, at utang."),
        "dua_sayyidul_istighfar" to DuaText("Ang punong panalangin ng paghingi ng tawad (Sayyidul Istighfar)", "O Allah, Ikaw ang aking Panginoon, walang diyos maliban sa Iyo. Nilikha Mo ako at ako ay Iyong lingkod. Nananatili ako sa Iyong tipan at pangako hangga't kaya ko. Nagpapakupkop ako sa Iyo laban sa kasamaang aking nagawa. Kinikilala ko ang Iyong biyaya sa akin at kinikilala ko ang aking kasalanan; patawarin Mo ako, sapagkat walang nagpapatawad ng kasalanan kundi Ikaw.", "Binibigkas sa umaga at gabi — ang pinakamahusay na panalangin ng pagsisisi na itinuro ng Propeta ﷺ.", "Ang bumigkas nito sa gabi nang may matibay na paniniwala at namatay nang gabing iyon ay papasok sa Paraiso; gayundin ang bumibigkas nito sa umaga."),
        "dua_parents" to DuaText("Panalangin para sa mga magulang", "Panginoon ko, kaawaan Mo sila kung paanong sila ay nag-alaga sa akin noong ako'y bata pa.", "Panalangin mula sa Qur'an bilang kabayaran sa pag-aalaga ng mga magulang noong bata pa.", "Direktang iniutos ng Allah ang panalanging ito para sa mga magulang sa Qur'an."),
        "dua_entering_mosque" to DuaText("Pagpasok sa moske", "O Allah, buksan Mo para sa akin ang mga pinto ng Iyong awa.", "Binibigkas pagpasok sa moske na may kanang paa.", "Itinuro ng Propeta ﷺ ang panalanging ito sa pagpasok ng moske."),
        "dua_morning_asbahna" to DuaText("Pag-alaala sa umaga", "Sumapit kami sa umaga at ang kaharian ay sa Allah; ang papuri ay sa Allah; walang diyos maliban sa Allah nang nag-iisa, walang katambal; sa Kanya ang kaharian at ang papuri, at Siya ay Makapangyarihan sa lahat ng bagay.", "Inirerekomendang pag-alaala na binibigkas sa umaga.", "Simulan ang araw sa pagkilala sa kapangyarihan at kaisahan ng Allah."),
        "dua_evening_amsayna" to DuaText("Pag-alaala sa gabi", "Sumapit kami sa gabi at ang kaharian ay sa Allah; ang papuri ay sa Allah; walang diyos maliban sa Allah nang nag-iisa, walang katambal; sa Kanya ang kaharian at ang papuri, at Siya ay Makapangyarihan sa lahat ng bagay.", "Inirerekomendang pag-alaala na binibigkas sa gabi.", "Simulan ang gabi sa pagkilala sa kapangyarihan at kaisahan ng Allah."),
        "dua_before_sleep" to DuaText("Bago matulog", "Sa Iyong ngalan, O Allah, ako ay namamatay at nabubuhay.", "Binibigkas matapos humiga upang matulog.", "Binibigkas ito ng Propeta ﷺ bago matulog."),
        "dua_travel" to DuaText("Panalangin sa paglalakbay", "Luwalhati sa Kanya na nagpasilbi nito para sa amin, gayong hindi namin ito makayang gawin; at tunay na sa aming Panginoon kami ay babalik.", "Binibigkas pagsakay sa sasakyan matapos ang tatlong takbir.", "Inirerekomendang panalangin sa paglalakbay para sa proteksyon at biyaya."),
        "dua_ayatul_kursi" to DuaText("Ayatul Kursi matapos ang panalangin", "Ang Allah, walang diyos maliban sa Kanya, ang Buhay, ang Tagapangalaga ng lahat. Hindi Siya inaabot ng antok ni ng tulog. Sa Kanya ang lahat ng nasa langit at lupa. Sino ang makapamamagitan sa Kanya maliban sa Kanyang pahintulot? Nalalaman Niya ang nasa harap at likod nila. Wala silang maaabot sa Kanyang kaalaman maliban sa Kanyang naisin. Sumasaklaw ang Kanyang Trono sa mga langit at lupa, at hindi Siya nabibigatan sa pangangalaga sa mga ito. Siya ang Kataas-taasan, ang Dakila.", "Binibigkas matapos ang bawat obligadong panalangin at bago matulog.", "Ang bumigkas nito matapos ang bawat obligadong panalangin ay walang hahadlang sa kanya sa Paraiso maliban sa kamatayan; ang bumigkas bago matulog ay protektado hanggang umaga."),
        "dua_hasbunallah" to DuaText("Sapat na sa amin ang Allah", "Sapat na sa amin ang Allah at Siya ang pinakamahusay na Tagapag-ingat.", "Binibigkas sa oras ng takot sa kaaway o malaking panganib.", "Ito ang sinabi ni Abraham nang siya ay itapon sa apoy, at sinabi rin ito ng Propeta ﷺ sa oras ng panganib."),
        "dua_entering_home" to DuaText("Pagpasok sa bahay", "Sa ngalan ng Allah kami pumasok, sa ngalan ng Allah kami lumabas, at sa aming Panginoong Allah kami nagtitiwala.", "Binibigkas pagpasok sa bahay habang binabanggit ang ngalan ng Allah at nagbibigay ng pagbati.", "Sa taong umaalala sa Allah pagpasok ng bahay at pagkain, sasabihin ng satanas: walang matutuluyan o hapunan para sa inyo."),
        "dua_yunus" to DuaText("Panalangin ni Propeta Jonas (kapayapaan sa kanya)", "Walang diyos maliban sa Iyo, luwalhati sa Iyo; tunay na ako ay naging isa sa mga makasalanan.", "Panalangin ni Propeta Jonas sa loob ng tiyan ng isda — para sa lahat ng kahirapan.", "Walang Muslim na dumadalangin nito para sa anumang bagay maliban sa sasagutin siya ng Allah."),
        "dua_karb" to DuaText("Panalangin sa matinding paghihirap", "Walang diyos maliban sa Allah, ang Dakila, ang Mapagpaumanhin. Walang diyos maliban sa Allah, Panginoon ng dakilang Trono. Walang diyos maliban sa Allah, Panginoon ng mga langit, ng lupa, at ng marangal na Trono.", "Binibigkas sa matinding paghihirap at kahirapan.", "Binibigkas ito ng Propeta ﷺ sa oras ng matinding paghihirap."),
    )
}
